const __pageData = JSON.parse('{"title":"3.13 Initial Acquaintance with Embodied Intelligence","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Teaching Case/3.13 Initial Acquaintance with Embodied Intelligence.md","filePath":"docs/3. Teaching Case/3.13 Initial Acquaintance with Embodied Intelligence.md"}');
